// AUDITORIA C-3: o webhook do n8n nao tinha autenticacao. Este no rejeita
// qualquer requisicao que nao traga o header X-Webhook-Token com o valor
// de $env.WHATSAPP_WEBHOOK_TOKEN. Fail-closed: se o env nao estiver setado,
// nada passa.
const expected = ($env.WHATSAPP_WEBHOOK_TOKEN || '').trim();
const headers = ($input.first().json.headers) || {};
const got = (headers['x-webhook-token'] || headers['X-Webhook-Token'] || '').toString().trim();
if (!expected || got !== expected) {
  throw new Error('webhook nao autorizado (X-Webhook-Token ausente ou invalido)');
}
return $input.all();

